//! Embedded icons (generated by `tools/gen-icons`).

const APP_PNG: &[u8] = include_bytes!("../../../assets/icon/fennec-256.png");
#[cfg(windows)]
const TRAY_PNG: &[u8] = include_bytes!("../../../assets/icon/fennec-tray-32.png");

/// Decodes a PNG into RGBA8.
pub fn decode_png(bytes: &[u8]) -> Option<(Vec<u8>, u32, u32)> {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(png::Transformations::EXPAND);
    let mut reader = decoder.read_info().ok()?;
    let mut buf = vec![0; reader.output_buffer_size()?];
    let info = reader.next_frame(&mut buf).ok()?;
    buf.truncate(info.buffer_size());
    match info.color_type {
        png::ColorType::Rgba => Some((buf, info.width, info.height)),
        png::ColorType::Rgb => {
            let rgba = buf.as_chunks::<3>().0.iter().flat_map(|c| [c[0], c[1], c[2], 255]).collect();
            Some((rgba, info.width, info.height))
        }
        _ => None,
    }
}

/// Window icon.
pub fn app_icon() -> Option<egui::IconData> {
    let (rgba, width, height) = decode_png(APP_PNG)?;
    Some(egui::IconData { rgba, width, height })
}

/// Monochrome tray icon (RGBA, width, height).
#[cfg(windows)]
pub fn tray_rgba() -> Option<(Vec<u8>, u32, u32)> {
    decode_png(TRAY_PNG)
}

#[cfg(test)]
mod tests {
    #[test]
    fn embedded_icon_decodes() {
        let icon = super::app_icon().unwrap();
        assert_eq!((icon.width, icon.height), (256, 256));
        assert_eq!(icon.rgba.len(), 256 * 256 * 4);
        // Corners are transparent (rounded background), the centre is opaque.
        assert_eq!(icon.rgba[3], 0);
        assert_eq!(icon.rgba[(128 * 256 + 128) * 4 + 3], 255);
    }
}
